{
  "narratives": [
    {
      "item_code": "S5_MEDIA",
      "title_raw": "가. 적절한(부적절한) 소화제",
      "start": "p3:L13",
      "end": "p3:L20"
    },
    {
      "item_code": "S5_SPECIFIC",
      "title_raw": "나. 화학물질로부터 생기는 특정 유해성",
      "start": "p3:L21",
      "end": "p3:L32"
    },
    {
      "item_code": "S5_FIREFIGHT",
      "title_raw": "다. 화재진압시 착용할 보호구 및 예방조치",
      "start": "p4:L2",
      "end": "p4:L15"
    }
  ],
  "extras": [
    {
      "after_item": "S5_MEDIA",
      "title_raw": "○ 적절한 소화제",
      "reason": "필드없음",
      "line": "p3:L14"
    },
    {
      "statements": [
        {
          "value": "CO2",
          "line": "p3:L15"
        },
        {
          "value": "건조화학제",
          "line": "p3:L16"
        },
        {
          "value": "이 물질과 관련된 소화시 알콜 포말, 이산화탄소 또는 물분무를 사용할 것.",
          "line": "p3:L17"
        },
        {
          "value": "질식소화시 건조한 모래 또는 흙을 사용할 것.",
          "line": "p3:L18"
        }
      ],
      "line": "p3:L14"
    },
    {
      "after_item": "S5_MEDIA",
      "title_raw": "○ 부적절한 소화제",
      "reason": "필드없음",
      "line": "p3:L19"
    },
    {
      "statements": [
        {
          "value": "자료없음",
          "line": "p3:L20"
        }
      ],
      "line": "p3:L19"
    },
    {
      "after_item": "S5_SPECIFIC",
      "title_raw": "○ 열분해성 생성물",
      "reason": "필드없음",
      "line": "p3:L22"
    },
    {
      "statements": [
        {
          "value": "자료없음",
          "line": "p3:L23"
        }
      ],
      "line": "p3:L22"
    },
    {
      "after_item": "S5_SPECIFIC",
      "title_raw": "○ 화재 및 폭발 위험",
      "reason": "필드없음",
      "line": "p3:L24"
    },
    {
      "statements": [
        {
          "value": "가열시 용기가 폭발할 수 있음.",
          "line": "p3:L25"
        },
        {
          "value": "가열시 증기는 공기와 혼합하여 폭발성 혼합물을 형성할 수 있음; 실내, 실외, 하수구에 폭발 위험.",
          "line": "p3:L26"
        },
        {
          "value": "격렬하게 중합반응하여 화재와 폭발을 일으킬 수 있음.",
          "line": "p3:L27"
        },
        {
          "value": "공기와 폭발성 혼합물을 형성함.",
          "line": "p3:L28"
        },
        {
          "value": "극인화성.",
          "line": "p3:L29"
        },
        {
          "value": "수소(UN No. 1049)/중수소(UN No. 1957)/압축수소메탄혼합물(UN No. 2034)는 화염이 눈에 보이지 않음.",
          "line": "p3:L30"
        },
        {
          "value": "열, 스파크, 화염에 의해 쉽게 점화함.",
          "line": "p3:L31"
        },
        {
          "value": "화재에 노출된 실린더는 가연성 가스를 방출할 수 있음.",
          "line": "p3:L32"
        }
      ],
      "line": "p3:L24"
    },
    {
      "after_item": "S5_SPECIFIC",
      "title_raw": "○ 기타",
      "reason": "필드없음",
      "line": "p3:L33"
    },
    {
      "statements": [
        {
          "value": "일부 물질은 고농도로 흡입시 자극적일 수 있음.",
          "line": "p3:L34"
        },
        {
          "value": "화재시 자극성, 부식성, 독성 가스를 발생할 수 있음.",
          "line": "p3:L35"
        },
        {
          "value": "화재에 노출된 실린더는 가연성 가스를 방출할 수 있음.",
          "line": "p3:L36"
        },
        {
          "value": "3",
          "line": "p3:L37"
        }
      ],
      "line": "p3:L33"
    }
  ]
}

